"""Deterministic SVG diagrams for CFFG templates.

The renderer is intentionally dependency-free. It lays out factors, variables,
parameter blobs, constraints, and ports on stable lanes inside a fixed-aspect
viewBox so small structural changes tend to appear as local visual changes.
"""

from __future__ import annotations

from dataclasses import dataclass
from html import escape
from pathlib import Path
import re
from statistics import median

from cffg.core.ir import Template


@dataclass(frozen=True)
class DiagramStyle:
    width: int = 1280
    height: int = 720
    margin_x: float = 90.0
    margin_y: float = 70.0
    column_gap: float = 620.0
    row_gap: float = 58.0
    node_width: float = 132.0
    node_height: float = 34.0
    font_family: str = "Inter, -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif"


@dataclass(frozen=True)
class _Node:
    key: str
    kind: str
    label: str
    detail: str
    column: int
    order: str


@dataclass(frozen=True)
class _Edge:
    source: str
    target: str
    label: str
    kind: str = "structural"


def render_template_svg(template: Template, *, style: DiagramStyle = DiagramStyle()) -> str:
    """Render `template` as a standalone SVG string.

    Layout is deterministic: node columns come from scoped time suffixes when
    available, otherwise from sorted connectivity. Nodes use fixed lanes by
    semantic kind, and the SVG viewBox expands while the visible aspect ratio
    remains fixed through `preserveAspectRatio`.
    """

    nodes, edges = _diagram_graph(template)
    positions, view_w, view_h = _layout(nodes, style)
    return _render_svg(template.name, nodes, edges, positions, view_w, view_h, style)


def save_template_svg(
    template: Template,
    path: str | Path,
    *,
    style: DiagramStyle = DiagramStyle(),
    overwrite: bool = True,
) -> bool:
    """Write a template diagram. Returns False when skipped by `overwrite=False`."""

    out = Path(path)
    if out.exists() and not overwrite:
        return False
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(render_template_svg(template, style=style))
    return True


def _diagram_graph(template: Template) -> tuple[list[_Node], list[_Edge]]:
    columns: dict[str, int] = {}
    for name in template.variables:
        columns[f"var:{name}"] = _column_from_name(name)
    for name, factor in template.factors.items():
        connected = [columns.get(f"var:{v}", _column_from_name(v)) for v in factor.all_edges().values()]
        columns[f"factor:{name}"] = int(round(median(connected))) if connected else _column_from_name(name)
    for name, port in template.ports.items():
        columns[f"port:{name}"] = columns.get(f"var:{port.variable}", _column_from_name(port.variable))
    for name, blob in template.blobs.items():
        users = [
            columns[f"factor:{factor.name}"]
            for factor in template.factors.values()
            if name in factor.param_blobs.values()
        ]
        columns[f"blob:{name}"] = int(round(median(users))) if users else _column_from_name(blob.name)
    for i, constraint in enumerate(template.constraints):
        target_key = (
            f"factor:{constraint.target}"
            if constraint.target in template.factors
            else f"var:{constraint.target}"
        )
        columns[f"constraint:{i}"] = columns.get(target_key, _column_from_name(constraint.target))

    nodes: list[_Node] = []
    for name, blob in sorted(template.blobs.items()):
        nodes.append(_Node(f"blob:{name}", "blob", name, blob.path, columns[f"blob:{name}"], name))
    for i, constraint in enumerate(template.constraints):
        detail = ", ".join(f"{k}={v}" for k, v in constraint.detail)
        nodes.append(
            _Node(
                f"constraint:{i}",
                "constraint",
                constraint.kind.value,
                f"{constraint.target}" + (f" | {detail}" if detail else ""),
                columns[f"constraint:{i}"],
                f"{constraint.kind.value}:{constraint.target}:{i}",
            )
        )
    for name, factor in sorted(template.factors.items()):
        nodes.append(
            _Node(
                f"factor:{name}",
                "factor",
                name,
                factor.type,
                columns[f"factor:{name}"],
                f"{_natural_key(name)}",
            )
        )
    for name, variable in sorted(template.variables.items()):
        detail = f"card {variable.cardinality}" if variable.cardinality > 0 else ""
        nodes.append(
            _Node(
                f"var:{name}",
                "variable",
                name,
                detail,
                columns[f"var:{name}"],
                f"{_natural_key(name)}",
            )
        )
    for name, port in sorted(template.ports.items()):
        nodes.append(
            _Node(
                f"port:{name}",
                "port",
                name,
                port.role.value,
                columns[f"port:{name}"],
                f"{port.role.value}:{_natural_key(name)}",
            )
        )

    edges: list[_Edge] = []
    for factor in sorted(template.factors.values(), key=lambda f: _natural_key(f.name)):
        for role, variable in sorted(factor.edges.items()):
            edges.append((_factor_var_edge(factor.name, variable, role, "structural")))
        for role, variable in sorted(factor.param_edges.items()):
            edges.append((_factor_var_edge(factor.name, variable, role, "parameter")))
        for role, blob in sorted(factor.param_blobs.items()):
            edges.append(_Edge(f"blob:{blob}", f"factor:{factor.name}", role, "parameter"))
    for name, port in sorted(template.ports.items()):
        edges.append(_Edge(f"var:{port.variable}", f"port:{name}", port.role.value, "port"))
    for i, constraint in enumerate(template.constraints):
        target = (
            f"factor:{constraint.target}"
            if constraint.target in template.factors
            else f"var:{constraint.target}"
        )
        edges.append(_Edge(f"constraint:{i}", target, constraint.kind.value, "constraint"))
    return nodes, edges


def _factor_var_edge(factor: str, variable: str, role: str, kind: str) -> _Edge:
    return _Edge(f"factor:{factor}", f"var:{variable}", role, kind)


def _layout(
    nodes: list[_Node], style: DiagramStyle
) -> tuple[dict[str, tuple[float, float]], float, float]:
    lanes = {
        "blob": 0,
        "constraint": 1,
        "factor": 2,
        "variable": 3,
        "port": 4,
    }
    x_offsets = {
        "blob": 0.0,
        "constraint": 100.0,
        "factor": 210.0,
        "variable": 410.0,
        "port": 560.0,
    }
    max_col = max((node.column for node in nodes), default=0)
    positions: dict[str, tuple[float, float]] = {}
    for kind, lane in lanes.items():
        by_col: dict[int, list[_Node]] = {}
        for node in nodes:
            if node.kind == kind:
                by_col.setdefault(node.column, []).append(node)
        for col, group in by_col.items():
            ordered = sorted(group, key=lambda n: n.order)
            x = style.margin_x + col * style.column_gap + x_offsets[kind]
            base_y = style.margin_y + lane * (style.row_gap * 2.0)
            for i, node in enumerate(ordered):
                positions[node.key] = (x, base_y + i * style.row_gap)

    max_rows = 1
    for kind in lanes:
        for col in range(max_col + 1):
            max_rows = max(max_rows, sum(1 for n in nodes if n.kind == kind and n.column == col))
    content_w = style.margin_x * 2 + max_col * style.column_gap + style.node_width + 620
    content_h = style.margin_y * 2 + 5 * style.row_gap * 2 + max_rows * style.row_gap
    view_w = max(style.width, content_w)
    view_h = max(style.height, content_h)
    aspect = style.width / style.height
    if view_w / view_h < aspect:
        view_w = view_h * aspect
    else:
        view_h = view_w / aspect
    return positions, view_w, view_h


def _render_svg(
    title: str,
    nodes: list[_Node],
    edges: list[_Edge],
    positions: dict[str, tuple[float, float]],
    view_w: float,
    view_h: float,
    style: DiagramStyle,
) -> str:
    css = f"""
    .bg {{ fill: #fbfaf7; }}
    .title {{ font: 700 24px {style.font_family}; fill: #1f2933; }}
    .legend {{ font: 500 13px {style.font_family}; fill: #52606d; }}
    .node text {{ font-family: {style.font_family}; text-anchor: middle; }}
    .label {{ font-size: 13px; font-weight: 700; fill: #17212b; }}
    .detail {{ font-size: 10px; fill: #52606d; }}
    .factor rect {{ fill: #e8f1ff; stroke: #2f68b7; }}
    .variable ellipse {{ fill: #f4f0ff; stroke: #7c5cc4; }}
    .blob path {{ fill: #eef8ef; stroke: #3b8a4b; }}
    .constraint rect {{ fill: #fff4df; stroke: #b7791f; stroke-dasharray: 5 3; }}
    .port rect {{ fill: #f4f6f8; stroke: #697386; }}
    .edge {{ fill: none; stroke: #7b8794; stroke-width: 1.4; }}
    .edge.parameter {{ stroke: #3b8a4b; stroke-dasharray: 4 3; }}
    .edge.constraint {{ stroke: #b7791f; stroke-dasharray: 5 4; }}
    .edge.port {{ stroke: #697386; stroke-dasharray: 2 4; }}
    .edge-label {{ font: 10px {style.font_family}; fill: #52606d; paint-order: stroke; stroke: #fbfaf7; stroke-width: 3px; }}
    """
    parts = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        (
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{style.width}" '
            f'height="{style.height}" viewBox="0 0 {view_w:.0f} {view_h:.0f}" '
            'preserveAspectRatio="xMidYMid meet">'
        ),
        f"<style>{css}</style>",
        '<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#7b8794"/></marker></defs>',
        f'<rect class="bg" width="{view_w:.0f}" height="{view_h:.0f}"/>',
        f'<text class="title" x="32" y="42">{escape(title)}</text>',
        '<text class="legend" x="32" y="64">rect=factor  ellipse=variable  green=parameter/blob  dashed=constraint/port</text>',
    ]

    for edge in sorted(edges, key=lambda e: (e.kind, e.source, e.target, e.label)):
        if edge.source not in positions or edge.target not in positions:
            continue
        x1, y1 = positions[edge.source]
        x2, y2 = positions[edge.target]
        y1 += style.node_height / 2
        y2 += style.node_height / 2
        mx, my = (x1 + x2) / 2, (y1 + y2) / 2
        parts.append(
            f'<path class="edge {edge.kind}" marker-end="url(#arrow)" d="M{x1:.1f},{y1:.1f} C{mx:.1f},{y1:.1f} {mx:.1f},{y2:.1f} {x2:.1f},{y2:.1f}"/>'
        )
        if edge.label:
            parts.append(f'<text class="edge-label" x="{mx:.1f}" y="{my - 4:.1f}">{escape(edge.label)}</text>')

    for node in sorted(nodes, key=lambda n: (n.kind, n.column, n.order)):
        x, y = positions[node.key]
        parts.append(_render_node(node, x, y, style))
    parts.append("</svg>\n")
    return "\n".join(parts)


def _render_node(node: _Node, x: float, y: float, style: DiagramStyle) -> str:
    w, h = style.node_width, style.node_height
    label = _shorten(node.label, 24)
    detail = _shorten(node.detail, 28)
    if node.kind == "variable":
        shape = f'<ellipse cx="{x:.1f}" cy="{y + h / 2:.1f}" rx="{w / 2:.1f}" ry="{h / 2:.1f}"/>'
    elif node.kind == "blob":
        shape = (
            f'<path d="M{x - w / 2:.1f},{y + 7:.1f} '
            f'C{x - w / 2:.1f},{y - 2:.1f} {x + w / 2:.1f},{y - 2:.1f} {x + w / 2:.1f},{y + 7:.1f} '
            f'L{x + w / 2:.1f},{y + h - 7:.1f} '
            f'C{x + w / 2:.1f},{y + h + 2:.1f} {x - w / 2:.1f},{y + h + 2:.1f} {x - w / 2:.1f},{y + h - 7:.1f} Z"/>'
        )
    else:
        rx = 12 if node.kind == "port" else 4
        shape = f'<rect x="{x - w / 2:.1f}" y="{y:.1f}" width="{w:.1f}" height="{h:.1f}" rx="{rx}"/>'
    detail_text = (
        f'<text class="detail" x="{x:.1f}" y="{y + 27:.1f}">{escape(detail)}</text>'
        if detail
        else ""
    )
    return (
        f'<g class="node {node.kind}">{shape}'
        f'<text class="label" x="{x:.1f}" y="{y + 16:.1f}">{escape(label)}</text>'
        f"{detail_text}</g>"
    )


def _shorten(text: str, max_chars: int) -> str:
    if len(text) <= max_chars:
        return text
    return text[: max_chars - 1] + "..."


def _column_from_name(name: str) -> int:
    if "/" in name:
        prefix = name.rsplit("/", 1)[0]
        match = re.search(r"(?:^|/)t(\d+)(?:/|$)", prefix)
        if match:
            return int(match.group(1))
    match = re.search(r"(\d+)$", name)
    return int(match.group(1)) if match else 0


def _natural_key(value: str) -> tuple[object, ...]:
    parts = re.split(r"(\d+)", value)
    return tuple(int(p) if p.isdigit() else p for p in parts)

"""Shared fixtures: a canonical HMM time-slice template.

One slice of the state-space model from Part II Fig. 7 (minus controls):
transition into z, an equality node exposing z to the observation branch and
to the next slice, observation factor emitting x. Glue ports head/tail chain
slices; the data port awaits an observation clamp.

    head(z_in) --[trans]-- z_mid --[eq]-- z_out : tail
                            |
                          z_obs --[obs]-- x : data
"""

import jax
import pytest

jax.config.update("jax_enable_x64", True)  # FE parity tests need f64

from cffg.core import (
    BlobRef,
    FactorSpec,
    PortRole,
    PortSpec,
    Template,
    VariableSpec,
)

K = 3  # latent cardinality
M = 2  # observation cardinality


def make_hmm_slice(name: str = "hmm_slice") -> Template:
    return Template(
        name=name,
        variables={
            "z_in": VariableSpec("z_in", K),
            "z_mid": VariableSpec("z_mid", K),
            "z_obs": VariableSpec("z_obs", K),
            "z_out": VariableSpec("z_out", K),
            "x": VariableSpec("x", M),
        },
        factors={
            "trans": FactorSpec(
                "trans", "matrix_cat", edges={"out": "z_mid", "in": "z_in"}, param_blobs={"matrix": "B"}
            ),
            "eq": FactorSpec("eq", "equality", edges={"a": "z_mid", "b": "z_obs", "c": "z_out"}),
            "obs": FactorSpec(
                "obs", "matrix_cat", edges={"out": "x", "in": "z_obs"}, param_blobs={"matrix": "A"}
            ),
        },
        ports={
            "head": PortSpec("head", "z_in", PortRole.GLUE),
            "tail": PortSpec("tail", "z_out", PortRole.GLUE),
            "sense": PortSpec("sense", "x", PortRole.DATA),
        },
        blobs={
            "A": BlobRef("A", "blobs/A.safetensors"),
            "B": BlobRef("B", "blobs/B.safetensors"),
        },
    )


@pytest.fixture
def hmm_slice() -> Template:
    return make_hmm_slice()

input.content:
"""Semantic diagram model: a Template expressed in CFFG visual algebra.

This is the level-independent middle representation between the IR and the
renderer. It answers "what is drawn" (Part I §5): factor boxes with their
q-marginal bead structure, wires with on-wire beads, pointmass/data terminals,
rollout ellipses at glue ports, and GFE composite boxes. It does *not* answer
"where" (layout) or "at which compression level" (the p.19 passes) — those
are separate stages that consume this model.

The derivation makes the papers' default explicit: with no annotations, q has
a joint marginal per node and a normalisation bead per internal edge. Every
ConstraintSpec, port, and parameter binding then perturbs that default:

- ``MEAN_FIELD``       -> one bead per q-edge instead of the joint bead
- ``P_SUBSTITUTION``   -> the substituted role's bead becomes a square (Fig 13)
- ``DELTA`` on an edge -> the on-wire bead carries a delta symbol (Fig 11)
- ``param_blobs``      -> black-square pointmass terminal (Fig 10 discussion);
                          the role drops out of q, so the node loses its
                          default factorisation (the f_d case, Fig 16)
- DATA ports           -> filled, terminating data bead (Fig 10)
- GLUE ports           -> ellipsis: the model continues by composition
- GOAL/PRIOR ports     -> dangling edge terminated by an (empty) bead (§5.2)
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum

from cffg.core.ir import (
    ConstraintKind,
    ConstraintSpec,
    FACTOR_TYPES,
    FactorSpec,
    PortRole,
    Template,
)

# Conventional glyphs used by the papers' figures (Part I Figs 22/26).
GLYPHS = {
    "categorical": "Cat",
    "matrix_cat": "T",
    "transition_mixture": "TM",
    "equality": "=",
    "dirichlet": "Dir",
}


class BeadShape(str, Enum):
    CIRCLE = "circle"  # marginal of q
    SQUARE = "square"  # P-substituted: p(x|rest) used in expectation (Fig 13)


class TerminalKind(str, Enum):
    POINTMASS = "pointmass"  # black square: delta-distributed model parameter
    DATA = "data"  # filled delta bead: observation clamp, terminates the edge
    OPEN = "open"  # dangling edge terminated by a bead (form-constraint anchor)
    ELLIPSIS = "ellipsis"  # glue port: the graph continues by composition


@dataclass(frozen=True)
class NodeEnd:
    """A wire endpoint attached to a factor box at a named role."""

    factor: str
    role: str


@dataclass(frozen=True)
class TerminalEnd:
    """A wire endpoint that terminates outside any factor box."""

    kind: TerminalKind
    label: str = ""  # blob or port name
    ref: str = ""  # "blob:<name>" or "port:<name>" back-reference


@dataclass(frozen=True)
class WireView:
    """A drawable edge. `id` is "var:<name>" or "blob:<factor>.<role>"."""

    id: str
    label: str  # variable name; empty for parameter wires (terminal is labeled)
    ends: tuple[NodeEnd | TerminalEnd, NodeEnd | TerminalEnd]
    bead: str | None = None  # None: no bead in q (pointmass wires); "": empty
    # bead symbols: "" (default normalisation), "delta", "E" (moment matching)

    def node_ends(self) -> list[NodeEnd]:
        return [e for e in self.ends if isinstance(e, NodeEnd)]


@dataclass(frozen=True)
class BeadGroup:
    """One factor of the node's q-marginal: q^n(s_a^n) over `roles` (§5.1)."""

    roles: tuple[str, ...]
    shape: BeadShape = BeadShape.CIRCLE
    symbol: str = ""


@dataclass(frozen=True)
class NodeView:
    factor: str
    type: str
    glyph: str
    groups: tuple[BeadGroup, ...]  # factorisation of q(s_a) over q-roles
    pointmass_roles: tuple[str, ...]  # roles absent from q (blobs, data clamps)
    default_factorisation: bool  # joint over *all* edges: nothing to draw
    # when compressed (steps 2-3 of the p.19 recipe apply to this node)


@dataclass(frozen=True)
class CompositeView:
    """A GFE composite (Part II §4): dashed box around obs + goal factors."""

    name: str
    members: tuple[str, ...]  # (observation factor, goal factor)
    x_variable: str  # the P-substituted edge joining them


@dataclass
class Diagram:
    name: str
    nodes: dict[str, NodeView] = field(default_factory=dict)
    wires: dict[str, WireView] = field(default_factory=dict)
    composites: list[CompositeView] = field(default_factory=list)

    def wires_of(self, factor: str) -> list[WireView]:
        return [w for w in self.wires.values() if any(e.factor == factor for e in w.node_ends())]


_PORT_TERMINALS = {
    PortRole.DATA: TerminalKind.DATA,
    PortRole.GLUE: TerminalKind.ELLIPSIS,
    PortRole.GOAL: TerminalKind.OPEN,
    PortRole.PRIOR: TerminalKind.OPEN,
}


def derive(template: Template) -> Diagram:
    """Express `template` in the visual algebra, at full (level-0) detail."""

    node_constraints: dict[str, list[ConstraintSpec]] = {}
    edge_constraints: dict[str, list[ConstraintSpec]] = {}
    for c in template.constraints:
        bucket = edge_constraints if c.target in template.variables else node_constraints
        bucket.setdefault(c.target, []).append(c)

    data_clamped = {
        p.variable for p in template.ports.values() if p.role is PortRole.DATA
    }

    diagram = Diagram(name=template.name)
    for f in template.factors.values():
        diagram.nodes[f.name] = _node_view(f, node_constraints.get(f.name, []), data_clamped)

    endpoints: dict[str, list[NodeEnd]] = {v: [] for v in template.variables}
    for f in template.factors.values():
        for role, var in f.all_edges().items():
            endpoints[var].append(NodeEnd(f.name, role))

    for var, ends in endpoints.items():
        diagram.wires[f"var:{var}"] = _variable_wire(
            template, var, ends, edge_constraints.get(var, [])
        )
    for f in template.factors.values():
        for role, blob in sorted(f.param_blobs.items()):
            wid = f"blob:{f.name}.{role}"
            diagram.wires[wid] = WireView(
                id=wid,
                label="",
                ends=(
                    NodeEnd(f.name, role),
                    TerminalEnd(TerminalKind.POINTMASS, label=blob, ref=f"blob:{blob}"),
                ),
                bead=None,  # pointmass in the model: not a factor of q
            )

    diagram.composites = _detect_composites(template, node_constraints)
    return diagram


def _psub_role(constraints: list[ConstraintSpec]) -> str | None:
    for c in constraints:
        if c.kind is ConstraintKind.P_SUBSTITUTION:
            return c.detail_dict().get("substituted_role", "out")
    return None


def _node_view(
    f: FactorSpec, constraints: list[ConstraintSpec], data_clamped: set[str]
) -> NodeView:
    ftype = FACTOR_TYPES.get(f.type)
    # Stable role order: the type's declared order, then any extras.
    declared = (*ftype.edge_roles, *ftype.param_roles) if ftype else ()
    all_roles = [r for r in declared if r in f.all_edges() or r in f.param_blobs]
    all_roles += [r for r in {**f.all_edges(), **f.param_blobs} if r not in all_roles]

    pointmass = tuple(
        r
        for r in all_roles
        if r in f.param_blobs or f.all_edges().get(r) in data_clamped
    )
    q_roles = [r for r in all_roles if r not in pointmass]

    psub = _psub_role(constraints)
    mean_field = any(c.kind is ConstraintKind.MEAN_FIELD for c in constraints)

    groups: list[BeadGroup] = []
    plain = [r for r in q_roles if r != psub]
    if mean_field:
        groups += [BeadGroup((r,)) for r in plain]
    elif plain:
        groups.append(BeadGroup(tuple(plain)))
    if psub is not None:
        groups.append(BeadGroup((psub,), shape=BeadShape.SQUARE))

    return NodeView(
        factor=f.name,
        type=f.type,
        glyph=GLYPHS.get(f.type, f.type),
        groups=tuple(groups),
        pointmass_roles=pointmass,
        default_factorisation=not mean_field and psub is None and not pointmass,
    )


def _variable_wire(
    template: Template,
    var: str,
    ends: list[NodeEnd],
    constraints: list[ConstraintSpec],
) -> WireView:
    symbol = ""
    bead: str | None = ""
    for c in constraints:
        if c.kind is ConstraintKind.DELTA:
            symbol = "delta"

    pair: tuple[NodeEnd | TerminalEnd, NodeEnd | TerminalEnd]
    ports = template.ports_of(var)
    if len(ends) == 2:
        pair = (ends[0], ends[1])
    elif ends and ports:
        port = ports[0]
        kind = _PORT_TERMINALS[port.role]
        if kind is TerminalKind.DATA:
            bead = None  # the filled terminal *is* the (pointmass) bead
        pair = (ends[0], TerminalEnd(kind, label=port.name, ref=f"port:{port.name}"))
    elif ends:
        # Degree-1 edge without a port: invalid per cffg.core.validate, but
        # drawing it (terminated by a bead, §5.2) beats crashing the renderer.
        pair = (ends[0], TerminalEnd(TerminalKind.OPEN, label=var))
    else:
        raise ValueError(f"variable {var!r} is connected to no factor")
    return WireView(id=f"var:{var}", label=var, ends=pair, bead=symbol if bead == "" else bead)


def _detect_composites(
    template: Template, node_constraints: dict[str, list[ConstraintSpec]]
) -> list[CompositeView]:
    """Template-level mirror of the compiler's GFE-composite detection
    (cffg.compiler: P-substituted matrix_cat facing a fixed-statistic goal).
    Tolerant where the compiler errors: an unmatched P-substitution simply
    renders as a bare square bead with no dashed box.
    """

    composites: list[CompositeView] = []
    for fname, constraints in sorted(node_constraints.items()):
        f = template.factors.get(fname)
        if f is None or f.type != "matrix_cat" or _psub_role(constraints) != "out":
            continue
        x_var = f.edges["out"]
        facing = [
            g
            for g in template.factors.values()
            if g.name != fname and x_var in g.all_edges().values()
        ]
        if not facing:
            continue
        goal = facing[0]
        if goal.type == "categorical" and "statistic" in goal.param_blobs:
            composites.append(
                CompositeView(
                    name=f"gfe:{fname}", members=(fname, goal.name), x_variable=x_var
                )
            )
    return composites

toolUseResult.content:
"""Semantic diagram model: a Template expressed in CFFG visual algebra.

This is the level-independent middle representation between the IR and the
renderer. It answers "what is drawn" (Part I §5): factor boxes with their
q-marginal bead structure, wires with on-wire beads, pointmass/data terminals,
rollout ellipses at glue ports, and GFE composite boxes. It does *not* answer
"where" (layout) or "at which compression level" (the p.19 passes) — those
are separate stages that consume this model.

The derivation makes the papers' default explicit: with no annotations, q has
a joint marginal per node and a normalisation bead per internal edge. Every
ConstraintSpec, port, and parameter binding then perturbs that default:

- ``MEAN_FIELD``       -> one bead per q-edge instead of the joint bead
- ``P_SUBSTITUTION``   -> the substituted role's bead becomes a square (Fig 13)
- ``DELTA`` on an edge -> the on-wire bead carries a delta symbol (Fig 11)
- ``param_blobs``      -> black-square pointmass terminal (Fig 10 discussion);
                          the role drops out of q, so the node loses its
                          default factorisation (the f_d case, Fig 16)
- DATA ports           -> filled, terminating data bead (Fig 10)
- GLUE ports           -> ellipsis: the model continues by composition
- GOAL/PRIOR ports     -> dangling edge terminated by an (empty) bead (§5.2)
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum

from cffg.core.ir import (
    ConstraintKind,
    ConstraintSpec,
    FACTOR_TYPES,
    FactorSpec,
    PortRole,
    Template,
)

# Conventional glyphs used by the papers' figures (Part I Figs 22/26).
GLYPHS = {
    "categorical": "Cat",
    "matrix_cat": "T",
    "transition_mixture": "TM",
    "equality": "=",
    "dirichlet": "Dir",
}


class BeadShape(str, Enum):
    CIRCLE = "circle"  # marginal of q
    SQUARE = "square"  # P-substituted: p(x|rest) used in expectation (Fig 13)


class TerminalKind(str, Enum):
    POINTMASS = "pointmass"  # black square: delta-distributed model parameter
    DATA = "data"  # filled delta bead: observation clamp, terminates the edge
    OPEN = "open"  # dangling edge terminated by a bead (form-constraint anchor)
    ELLIPSIS = "ellipsis"  # glue port: the graph continues by composition


@dataclass(frozen=True)
class NodeEnd:
    """A wire endpoint attached to a factor box at a named role."""

    factor: str
    role: str


@dataclass(frozen=True)
class TerminalEnd:
    """A wire endpoint that terminates outside any factor box."""

    kind: TerminalKind
    label: str = ""  # blob or port name
    ref: str = ""  # "blob:<name>" or "port:<name>" back-reference


@dataclass(frozen=True)
class WireView:
    """A drawable edge. `id` is "var:<name>" or "blob:<factor>.<role>"."""

    id: str
    label: str  # variable name; empty for parameter wires (terminal is labeled)
    ends: tuple[NodeEnd | TerminalEnd, NodeEnd | TerminalEnd]
    bead: str | None = None  # None: no bead in q (pointmass wires); "": empty
    # bead symbols: "" (default normalisation), "delta", "E" (moment matching)

    def node_ends(self) -> list[NodeEnd]:
        return [e for e in self.ends if isinstance(e, NodeEnd)]


@dataclass(frozen=True)
class BeadGroup:
    """One factor of the node's q-marginal: q^n(s_a^n) over `roles` (§5.1)."""

    roles: tuple[str, ...]
    shape: BeadShape = BeadShape.CIRCLE
    symbol: str = ""


@dataclass(frozen=True)
class NodeView:
    factor: str
    type: str
    glyph: str
    groups: tuple[BeadGroup, ...]  # factorisation of q(s_a) over q-roles
    pointmass_roles: tuple[str, ...]  # roles absent from q (blobs, data clamps)
    default_factorisation: bool  # joint over *all* edges: nothing to draw
    # when compressed (steps 2-3 of the p.19 recipe apply to this node)


@dataclass(frozen=True)
class CompositeView:
    """A GFE composite (Part II §4): dashed box around obs + goal factors."""

    name: str
    members: tuple[str, ...]  # (observation factor, goal factor)
    x_variable: str  # the P-substituted edge joining them


@dataclass
class Diagram:
    name: str
    nodes: dict[str, NodeView] = field(default_factory=dict)
    wires: dict[str, WireView] = field(default_factory=dict)
    composites: list[CompositeView] = field(default_factory=list)

    def wires_of(self, factor: str) -> list[WireView]:
        return [w for w in self.wires.values() if any(e.factor == factor for e in w.node_ends())]


_PORT_TERMINALS = {
    PortRole.DATA: TerminalKind.DATA,
    PortRole.GLUE: TerminalKind.ELLIPSIS,
    PortRole.GOAL: TerminalKind.OPEN,
    PortRole.PRIOR: TerminalKind.OPEN,
}


def derive(template: Template) -> Diagram:
    """Express `template` in the visual algebra, at full (level-0) detail."""

    node_constraints: dict[str, list[ConstraintSpec]] = {}
    edge_constraints: dict[str, list[ConstraintSpec]] = {}
    for c in template.constraints:
        bucket = edge_constraints if c.target in template.variables else node_constraints
        bucket.setdefault(c.target, []).append(c)

    data_clamped = {
        p.variable for p in template.ports.values() if p.role is PortRole.DATA
    }

    diagram = Diagram(name=template.name)
    for f in template.factors.values():
        diagram.nodes[f.name] = _node_view(f, node_constraints.get(f.name, []), data_clamped)

    endpoints: dict[str, list[NodeEnd]] = {v: [] for v in template.variables}
    for f in template.factors.values():
        for role, var in f.all_edges().items():
            endpoints[var].append(NodeEnd(f.name, role))

    for var, ends in endpoints.items():
        diagram.wires[f"var:{var}"] = _variable_wire(
            template, var, ends, edge_constraints.get(var, [])
        )
    for f in template.factors.values():
        for role, blob in sorted(f.param_blobs.items()):
            wid = f"blob:{f.name}.{role}"
            diagram.wires[wid] = WireView(
                id=wid,
                label="",
                ends=(
                    NodeEnd(f.name, role),
                    TerminalEnd(TerminalKind.POINTMASS, label=blob, ref=f"blob:{blob}"),
                ),
                bead=None,  # pointmass in the model: not a factor of q
            )

    diagram.composites = _detect_composites(template, node_constraints)
    return diagram


def _psub_role(constraints: list[ConstraintSpec]) -> str | None:
    for c in constraints:
        if c.kind is ConstraintKind.P_SUBSTITUTION:
            return c.detail_dict().get("substituted_role", "out")
    return None


def _node_view(
    f: FactorSpec, constraints: list[ConstraintSpec], data_clamped: set[str]
) -> NodeView:
    ftype = FACTOR_TYPES.get(f.type)
    # Stable role order: the type's declared order, then any extras.
    declared = (*ftype.edge_roles, *ftype.param_roles) if ftype else ()
    all_roles = [r for r in declared if r in f.all_edges() or r in f.param_blobs]
    all_roles += [r for r in {**f.all_edges(), **f.param_blobs} if r not in all_roles]

    pointmass = tuple(
        r
        for r in all_roles
        if r in f.param_blobs or f.all_edges().get(r) in data_clamped
    )
    q_roles = [r for r in all_roles if r not in pointmass]

    psub = _psub_role(constraints)
    mean_field = any(c.kind is ConstraintKind.MEAN_FIELD for c in constraints)

    groups: list[BeadGroup] = []
    plain = [r for r in q_roles if r != psub]
    if mean_field:
        groups += [BeadGroup((r,)) for r in plain]
    elif plain:
        groups.append(BeadGroup(tuple(plain)))
    if psub is not None:
        groups.append(BeadGroup((psub,), shape=BeadShape.SQUARE))

    return NodeView(
        factor=f.name,
        type=f.type,
        glyph=GLYPHS.get(f.type, f.type),
        groups=tuple(groups),
        pointmass_roles=pointmass,
        default_factorisation=not mean_field and psub is None and not pointmass,
    )


def _variable_wire(
    template: Template,
    var: str,
    ends: list[NodeEnd],
    constraints: list[ConstraintSpec],
) -> WireView:
    symbol = ""
    bead: str | None = ""
    for c in constraints:
        if c.kind is ConstraintKind.DELTA:
            symbol = "delta"

    pair: tuple[NodeEnd | TerminalEnd, NodeEnd | TerminalEnd]
    ports = template.ports_of(var)
    if len(ends) == 2:
        pair = (ends[0], ends[1])
    elif ends and ports:
        port = ports[0]
        kind = _PORT_TERMINALS[port.role]
        if kind is TerminalKind.DATA:
            bead = None  # the filled terminal *is* the (pointmass) bead
        pair = (ends[0], TerminalEnd(kind, label=port.name, ref=f"port:{port.name}"))
    elif ends:
        # Degree-1 edge without a port: invalid per cffg.core.validate, but
        # drawing it (terminated by a bead, §5.2) beats crashing the renderer.
        pair = (ends[0], TerminalEnd(TerminalKind.OPEN, label=var))
    else:
        raise ValueError(f"variable {var!r} is connected to no factor")
    return WireView(id=f"var:{var}", label=var, ends=pair, bead=symbol if bead == "" else bead)


def _detect_composites(
    template: Template, node_constraints: dict[str, list[ConstraintSpec]]
) -> list[CompositeView]:
    """Template-level mirror of the compiler's GFE-composite detection
    (cffg.compiler: P-substituted matrix_cat facing a fixed-statistic goal).
    Tolerant where the compiler errors: an unmatched P-substitution simply
    renders as a bare square bead with no dashed box.
    """

    composites: list[CompositeView] = []
    for fname, constraints in sorted(node_constraints.items()):
        f = template.factors.get(fname)
        if f is None or f.type != "matrix_cat" or _psub_role(constraints) != "out":
            continue
        x_var = f.edges["out"]
        facing = [
            g
            for g in template.factors.values()
            if g.name != fname and x_var in g.all_edges().values()
        ]
        if not facing:
            continue
        goal = facing[0]
        if goal.type == "categorical" and "statistic" in goal.param_blobs:
            composites.append(
                CompositeView(
                    name=f"gfe:{fname}", members=(fname, goal.name), x_variable=x_var
                )
            )
    return composites

input.content:
"""Deterministic rectilinear layout: diagram + presentation -> Scene.

The papers lay CFFGs out on an invisible grid (Figs 22/26): a horizontal
*rail* — the state chain — read left to right in time, control priors above
it, observation/goal branches hanging below, parameter terminals tucked into
the nearest free side. This module reproduces that convention:

- **Rail.** The path between glue-port factors (or from the far end of the
  graph to the single glue port). Composite members never sit on the rail.
  Orientation: the first-declared glue port is the left end; a single glue
  port is the right end (the model continues rightward, Fig 22's ellipsis).
- **Branches.** BFS from the rail: a branch attaching at a `selector` role
  goes above (control priors), everything else hangs below, one row per BFS
  depth (obs at +1, its goal at +2 — the Fig 26 stack).
- **Sides.** Structural wires claim box sides by neighbor direction; dangling
  port wires continue away from the rail; parameter terminals take the first
  free side in (left, up, down, right) order — which reproduces where the
  papers put d, A, B, c, and e.

Every decision is a pure function of names and topology — no global
optimisation — so an edit to the template moves only the rows/columns it
touches: the stability property the editing workflow needs.
"""

from __future__ import annotations

import re
from collections import deque
from dataclasses import dataclass, replace

from cffg.viz.compress import Placement, Presentation
from cffg.viz.diagram import (
    BeadShape,
    Diagram,
    NodeEnd,
    TerminalEnd,
    TerminalKind,
    WireView,
)
from cffg.viz.scene import (
    Bead,
    Box,
    CompositeBox,
    Dome,
    EllipsisMark,
    Path,
    Scene,
    Terminal,
)

# Unit direction vectors, y-down.
_DIRS = {"left": (-1, 0), "right": (1, 0), "up": (0, -1), "down": (0, 1)}
_TERMINAL_PREFERENCE = ("left", "up", "down", "right")


@dataclass(frozen=True)
class LayoutStyle:
    box: float = 58.0  # box side when beads live inside (levels 0-3)
    compact_box: float = 36.0  # fully compressed boxes (Fig 19 right)
    pitch_x: float = 128.0
    pitch_y: float = 104.0
    compact_pitch_x: float = 100.0
    compact_pitch_y: float = 84.0
    margin: float = 42.0
    bead_r: float = 6.0
    terminal_offset: float = 0.52  # of pitch, box center -> terminal center
    composite_pad: float = 13.0

    def sizes(self, compact: bool) -> tuple[float, float, float]:
        if compact:
            return self.compact_box, self.compact_pitch_x, self.compact_pitch_y
        return self.box, self.pitch_x, self.pitch_y


def natural_key(value: str) -> tuple[object, ...]:
    return tuple(int(p) if p.isdigit() else p for p in re.split(r"(\d+)", value))


def layout(
    diagram: Diagram, presentation: Presentation, style: LayoutStyle = LayoutStyle()
) -> Scene:
    grid, rail = _place_factors(diagram)
    sides = _assign_sides(diagram, grid, rail)
    return _emit(diagram, presentation, style, grid, sides)


# --------------------------------------------------------------------------
# Grid placement


def _adjacency(diagram: Diagram) -> dict[str, list[tuple[str, WireView]]]:
    adj: dict[str, list[tuple[str, WireView]]] = {n: [] for n in diagram.nodes}
    for wire in diagram.wires.values():
        ends = wire.node_ends()
        if len(ends) == 2 and ends[0].factor != ends[1].factor:
            adj[ends[0].factor].append((ends[1].factor, wire))
            adj[ends[1].factor].append((ends[0].factor, wire))
    for lst in adj.values():
        lst.sort(key=lambda t: natural_key(t[1].id))
    return adj


def _bfs_path(
    adj: dict[str, list[tuple[str, WireView]]],
    start: str,
    goal: str | None,
    allowed: set[str],
) -> list[str]:
    """Shortest path start->goal, or to the farthest reachable node."""
    prev: dict[str, str] = {}
    seen = {start}
    queue = deque([start])
    last = start
    while queue:
        cur = queue.popleft()
        last = cur
        if cur == goal:
            break
        for nxt, _ in adj[cur]:
            if nxt in allowed and nxt not in seen:
                seen.add(nxt)
                prev[nxt] = cur
                queue.append(nxt)
    end = goal if goal in seen else last
    path = [end]
    while path[-1] != start:
        path.append(prev[path[-1]])
    return path[::-1]


def _rail(diagram: Diagram, adj) -> list[str]:
    members = {m for c in diagram.composites for m in c.members}
    allowed = set(diagram.nodes) - members or set(diagram.nodes)

    glue: list[str] = []  # factors at glue ports, in wire declaration order
    for wire in diagram.wires.values():
        for end in wire.ends:
            if isinstance(end, TerminalEnd) and end.kind is TerminalKind.ELLIPSIS:
                (node,) = wire.node_ends()
                if node.factor not in glue:
                    glue.append(node.factor)

    if len(glue) >= 2:
        return _bfs_path(adj, glue[0], glue[1], allowed)
    if len(glue) == 1:
        far = _bfs_path(adj, glue[0], None, allowed)[-1]
        return _bfs_path(adj, far, glue[0], allowed)
    start = min(allowed, key=natural_key)
    a = _bfs_path(adj, start, None, allowed)[-1]
    b = _bfs_path(adj, a, None, allowed)[-1]
    path = _bfs_path(adj, a, b, allowed)
    return path if natural_key(path[0]) <= natural_key(path[-1]) else path[::-1]


def _place_factors(diagram: Diagram) -> tuple[dict[str, tuple[int, int]], list[str]]:
    adj = _adjacency(diagram)
    rail = _rail(diagram, adj)
    grid: dict[str, tuple[int, int]] = {f: (i, 0) for i, f in enumerate(rail)}
    occupied = set(grid.values())

    queue = deque((f, 0) for f in rail)  # (factor, inherited row direction)
    while queue:
        parent, direction = queue.popleft()
        pcol, prow = grid[parent]
        for child, wire in adj[parent]:
            if child in grid:
                continue
            role = next(e.role for e in wire.node_ends() if e.factor == parent)
            d = direction or (-1 if role == "selector" else 1)
            row = prow + d
            while (pcol, row) in occupied:
                row += d
            grid[child] = (pcol, row)
            occupied.add((pcol, row))
            queue.append((child, d))
    return grid, rail


# --------------------------------------------------------------------------
# Side assignment: which side of its box each wire end leaves from


def _assign_sides(
    diagram: Diagram, grid: dict[str, tuple[int, int]], rail: list[str]
) -> dict[tuple[str, str], str]:
    sides: dict[tuple[str, str], str] = {}
    taken: dict[str, set[str]] = {f: set() for f in grid}

    def claim(factor: str, role: str, side: str) -> None:
        sides[(factor, role)] = side
        taken[factor].add(side)

    def first_free(factor: str, preference: tuple[str, ...]) -> str:
        for side in preference:
            if side not in taken[factor]:
                return side
        return preference[0]

    structural, ports, blobs = [], [], []
    for wire in sorted(diagram.wires.values(), key=lambda w: natural_key(w.id)):
        ends = wire.node_ends()
        if len(ends) == 2:
            structural.append(wire)
        elif any(
            isinstance(e, TerminalEnd) and e.kind is TerminalKind.POINTMASS
            for e in wire.ends
        ):
            blobs.append(wire)
        else:
            ports.append(wire)

    for wire in structural:
        a, b = wire.ends
        (ax, ay), (bx, by) = grid[a.factor], grid[b.factor]
        if abs(bx - ax) >= abs(by - ay):
            claim(a.factor, a.role, "right" if bx >= ax else "left")
            claim(b.factor, b.role, "left" if bx >= ax else "right")
        else:
            claim(a.factor, a.role, "down" if by >= ay else "up")
            claim(b.factor, b.role, "up" if by >= ay else "down")

    for wire in ports:
        (node,) = wire.node_ends()
        term = next(e for e in wire.ends if isinstance(e, TerminalEnd))
        col, row = grid[node.factor]
        if term.kind is TerminalKind.ELLIPSIS and node.factor in rail:
            side = "left" if node.factor == rail[0] and "left" not in taken[node.factor] else "right"
        elif row < 0:
            side = first_free(node.factor, ("up", "left", "right", "down"))
        elif row > 0:
            side = first_free(node.factor, ("down", "left", "right", "up"))
        else:
            side = first_free(node.factor, ("up", "down", "left", "right"))
        claim(node.factor, node.role, side)

    for wire in blobs:
        (node,) = wire.node_ends()
        claim(node.factor, node.role, first_free(node.factor, _TERMINAL_PREFERENCE))
    return sides


# --------------------------------------------------------------------------
# Geometry


def _emit(
    diagram: Diagram,
    presentation: Presentation,
    style: LayoutStyle,
    grid: dict[str, tuple[int, int]],
    sides: dict[tuple[str, str], str],
) -> Scene:
    box, pitch_x, pitch_y = style.sizes(presentation.compact)
    centers = {f: (c * pitch_x, r * pitch_y) for f, (c, r) in grid.items()}

    anchors = _anchor_points(diagram, sides, centers, grid, box, (pitch_x, pitch_y))

    wires: list[Path] = []
    beads: list[Bead] = []
    terminals: list[Terminal] = []
    ellipses: list[EllipsisMark] = []

    for wire in diagram.wires.values():
        directive = presentation.wires[wire.id]
        pts, term_item, ellipsis_item = _wire_geometry(
            wire, anchors, centers, sides, style, (pitch_x, pitch_y)
        )
        label_at = _label_pos(pts, style) if wire.label else None
        wires.append(Path(wire.id, pts, label=wire.label, label_at=label_at))
        if term_item:
            terminals.append(term_item)
        if ellipsis_item:
            ellipses.append(ellipsis_item)
        if directive.bead:
            mx, my = _midpoint(pts)
            beads.append(Bead(wire.id, mx, my, BeadShape.CIRCLE, directive.symbol))

    boxes: list[Box] = []
    internal: list[Path] = []
    domes: list[Dome] = []
    for name, node in diagram.nodes.items():
        cx, cy = centers[name]
        boxes.append(Box(f"factor:{name}", cx, cy, box, box, node.glyph, name))
        directive = presentation.nodes[name]
        b, i, d = _node_marginals(name, node, directive, anchors, (cx, cy), style)
        beads += b
        internal += i
        domes += d

    composites = [
        _composite_box(c, centers, box, style) for c in diagram.composites
    ]

    items = [*composites, *wires, *internal, *boxes, *domes, *beads, *terminals, *ellipses]
    return _framed(diagram.name, items, style)


def _anchor_points(diagram, sides, centers, grid, box, pitch):
    """Pixel attachment point for every (factor, role): distribute the wires
    sharing a side along it, ordered by the far endpoint's position."""

    by_side: dict[tuple[str, str], list[tuple[float, str, str]]] = {}
    for wire in diagram.wires.values():
        ends = wire.node_ends()
        for end in ends:
            side = sides[(end.factor, end.role)]
            other = next((e for e in ends if e is not end), None)
            if other is not None:
                ox, oy = centers[other.factor]
                sort = oy if side in ("left", "right") else ox
            else:
                sort = 0.0
            by_side.setdefault((end.factor, side), []).append((sort, wire.id, end.role))

    anchors: dict[tuple[str, str], tuple[float, float, str]] = {}
    for (factor, side), entries in by_side.items():
        entries.sort(key=lambda e: (e[0], natural_key(e[1])))
        cx, cy = centers[factor]
        for i, (_, _, role) in enumerate(entries):
            frac = (i + 1) / (len(entries) + 1)
            if side == "left":
                pt = (cx - box / 2, cy - box / 2 + frac * box)
            elif side == "right":
                pt = (cx + box / 2, cy - box / 2 + frac * box)
            elif side == "up":
                pt = (cx - box / 2 + frac * box, cy - box / 2)
            else:
                pt = (cx - box / 2 + frac * box, cy + box / 2)
            anchors[(factor, role)] = (*pt, side)
    return anchors


def _wire_geometry(wire, anchors, centers, sides, style, pitch):
    pitch_x, pitch_y = pitch
    pts: list[tuple[float, float]] = []
    terminal = None
    ellipsis = None

    node_pts = []
    for end in wire.ends:
        if isinstance(end, NodeEnd):
            x, y, _ = anchors[(end.factor, end.role)]
            node_pts.append((x, y))
    if len(node_pts) == 2:
        pts = _route(node_pts[0], node_pts[1], _start_side(wire, anchors))
    else:
        (node,) = wire.node_ends()
        term = next(e for e in wire.ends if isinstance(e, TerminalEnd))
        x, y, side = anchors[(node.factor, node.role)]
        dx, dy = _DIRS[side]
        tx = x + dx * pitch_x * style.terminal_offset
        ty = y + dy * pitch_y * style.terminal_offset
        pts = [(x, y), (tx, ty)]
        ref = term.ref or wire.id
        if term.kind is TerminalKind.ELLIPSIS:
            angle = 0.0 if side in ("left", "right") else 90.0
            ellipsis = EllipsisMark(ref, tx, ty, angle)
        else:
            terminal = Terminal(ref, tx, ty, term.kind, term.label)
    return tuple(pts), terminal, ellipsis


def _start_side(wire, anchors):
    end = wire.node_ends()[0]
    return anchors[(end.factor, end.role)][2]


def _route(a, b, start_side) -> list[tuple[float, float]]:
    (x1, y1), (x2, y2) = a, b
    if abs(x1 - x2) < 0.5 or abs(y1 - y2) < 0.5:
        return [a, b]
    bend = (x2, y1) if start_side in ("left", "right") else (x1, y2)
    return [a, bend, b]


def _midpoint(pts) -> tuple[float, float]:
    """Midpoint of the longest segment (where a bead reads as 'on the wire')."""
    best, best_len = pts[:2], -1.0
    for p, q in zip(pts, pts[1:]):
        seg = abs(p[0] - q[0]) + abs(p[1] - q[1])
        if seg > best_len:
            best, best_len = (p, q), seg
    (x1, y1), (x2, y2) = best
    return (x1 + x2) / 2, (y1 + y2) / 2


def _label_pos(pts, style) -> tuple[float, float]:
    mx, my = _midpoint(pts)
    return mx + 5.0, my - 7.0


def _node_marginals(name, node, directive, anchors, center, style):
    """Bead/dome/internal-edge geometry for one node's q-marginal groups."""
    beads: list[Bead] = []
    internal: list[Path] = []
    domes: list[Dome] = []
    cx, cy = center
    ref = f"factor:{name}"

    for group in directive.groups:
        pts = [anchors.get((name, r)) for r in group.roles]
        pts = [p for p in pts if p is not None]
        if not pts:
            continue
        if directive.placement is Placement.BORDER:
            if len(pts) == 1 or group.shape is BeadShape.SQUARE:
                for x, y, _ in pts:
                    beads.append(Bead(ref, x, y, group.shape, group.symbol))
            else:
                domes.append(Dome(ref, tuple((x, y) for x, y, _ in pts), cx, cy))
        else:
            if len(pts) == 1:
                x, y, side = pts[0]
                dx, dy = _DIRS[side]
                bx, by = x - dx * style.bead_r * 1.9, y - dy * style.bead_r * 1.9
                beads.append(Bead(ref, bx, by, group.shape, group.symbol))
                if directive.internal_edges:
                    internal.append(Path(ref, ((x, y), (bx, by)), kind="internal"))
            else:
                beads.append(Bead(ref, cx, cy, group.shape, group.symbol))
                if directive.internal_edges:
                    for x, y, _ in pts:
                        internal.append(Path(ref, ((x, y), (cx, cy)), kind="internal"))
    return beads, internal, domes


def _composite_box(comp, centers, box, style) -> CompositeBox:
    xs, ys = zip(*(centers[m] for m in comp.members))
    pad = box / 2 + style.composite_pad
    return CompositeBox(
        f"gfe:{comp.name}",
        min(xs) - pad,
        min(ys) - pad,
        (max(xs) - min(xs)) + 2 * pad,
        (max(ys) - min(ys)) + 2 * pad,
    )


def _framed(name: str, items: list, style: LayoutStyle) -> Scene:
    """Translate everything into positive coordinates with a margin."""
    xs: list[float] = []
    ys: list[float] = []
    for item in items:
        for x, y in _item_points(item):
            xs.append(x)
            ys.append(y)
    dx = style.margin - min(xs, default=0.0)
    dy = style.margin - min(ys, default=0.0)
    moved = [_shift(item, dx, dy) for item in items]
    width = (max(xs, default=0.0) - min(xs, default=0.0)) + 2 * style.margin
    height = (max(ys, default=0.0) - min(ys, default=0.0)) + 2 * style.margin
    return Scene(name=name, width=width, height=height, items=moved)


def _item_points(item):
    if isinstance(item, Box):
        return [(item.x - item.w / 2 - 20, item.y - item.h / 2 - 20),
                (item.x + item.w / 2 + 20, item.y + item.h / 2 + 20)]
    if isinstance(item, Path):
        pts = list(item.points)
        if item.label_at:
            pts.append(item.label_at)
        return pts
    if isinstance(item, (Bead,)):
        return [(item.x - 10, item.y - 10), (item.x + 10, item.y + 10)]
    if isinstance(item, (Terminal, EllipsisMark)):
        return [(item.x - 26, item.y - 16), (item.x + 26, item.y + 16)]
    if isinstance(item, Dome):
        return list(item.anchors)
    if isinstance(item, CompositeBox):
        return [(item.x, item.y), (item.x + item.w, item.y + item.h)]
    return []


def _shift(item, dx: float, dy: float):
    if isinstance(item, Path):
        pts = tuple((x + dx, y + dy) for x, y in item.points)
        label_at = (
            (item.label_at[0] + dx, item.label_at[1] + dy) if item.label_at else None
        )
        return replace(item, points=pts, label_at=label_at)
    if isinstance(item, Dome):
        return replace(
            item,
            anchors=tuple((x + dx, y + dy) for x, y in item.anchors),
            cx=item.cx + dx,
            cy=item.cy + dy,
        )
    return replace(item, x=item.x + dx, y=item.y + dy)

