        cy = item.cy + (item.cy - my) * 0.9
        parts.append(f"Q{cx:.1f},{cy:.1f} {b[0]:.1f},{b[1]:.1f}")
    return f'<path d="{" ".join(parts)}"/>'


def _cross(a, b, c) -> float:
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


