def _bead(item: Bead, s: SvgStyle) -> str:
    r = s.bead_r
    if item.shape is BeadShape.SQUARE:
        shape = (
            f'<rect x="{item.x - r:.1f}" y="{item.y - r:.1f}" width="{2 * r:.1f}" '
